head.script:
scwin.makeGrid = function() {
    var gridStr = "";
    gridStr += '<w2:grid xmlns="http://www.w3.org/1999/xhtml" xmlns:ev="http://www.w3.org/2001/xml-events" xmlns:w2="http://www.inswave.com/websquare" xmlns:xf="http://www.w3.org/2002/xforms" dataList="dataList1" scrollByColumn="false" summaryAuto="false" scrollByColumnAdaptive="false" id="grid1" style="width: 500px;height: 150px;" ignoreCellClick="false" ignoreToggleOnDisabled="false" fixedColumnWithHidden="true" useShiftKey="true">';
    gridStr += '<w2:header id="header1" style="">';
    gridStr += '<w2:row id="row1" style="">';
    gridStr += '<w2:column blockSelect="false" id="column5" style="height:20px" inputType="text" width="70" displayMode="label" value="name1"></w2:column>';
    gridStr += '<w2:column blockSelect="false" id="column3" style="height:20px" inputType="text" width="70" displayMode="label" value="name2"></w2:column>';
    gridStr += '<w2:column blockSelect="false" id="column1" style="height:20px" width="70" inputType="text" displayMode="label" value="name3"></w2:column>';
    gridStr += '</w2:row>';
    gridStr += '</w2:header>';
    gridStr += '<w2:gBody id="gBody1" style="">';
    gridStr += '<w2:row id="row2" style="">';
    gridStr += '<w2:column blockSelect="false" id="col1" style="height:20px" inputType="text" width="70" displayMode="label"></w2:column>';
    gridStr += '<w2:column blockSelect="false" id="col2" style="height:20px" inputType="text" width="70" displayMode="label"></w2:column>';
    gridStr += '<w2:column blockSelect="false" id="col3" style="height:20px" width="70" inputType="text" displayMode="label"></w2:column>';
    gridStr += '</w2:row>';
    gridStr += '</w2:gBody>';
    gridStr += '</w2:grid>';
    WebSquare.util.dynamicCreate("grid1", "grid", gridStr, WebSquare.getBody());
}
scwin.__checkEl = function(id) {
    if (WebSquare.wUnit.getDomById(id)) {
        return true;
    }
    return false;
}
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "scwin.__checkEl('grid1_column5')", "true");
    WebSquare.wUnit.addCommand("assert", "scwin.__checkEl('grid1_column3')", "true");
    WebSquare.wUnit.addCommand("assert", "scwin.__checkEl('grid1_column1')", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.logger.getErrorLog() == ''", "true");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    scwin.makeGrid();
    //Function 
    //Created by: Thuyet.Pham
    //Created date: 23-Feb-2018
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
